#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int w;
    short u, v;
    bool operator<(const Edge& other) const {
        return w > other.w;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> x(N + 1), y(N + 1);
    x[0] = 0; y[0] = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> x[i] >> y[i];
    }

    auto dist2 = [&](int i, int j) -> int {
        int dx = x[i] - x[j];
        int dy = y[i] - y[j];
        return dx * dx + dy * dy;
    };

    vector<Edge> edges;
    edges.reserve(N + N * (N - 1));

    for (int i = 1; i <= N; ++i) {
        edges.push_back({dist2(0, i), 0, (short)i});
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (i != j) {
                edges.push_back({dist2(i, j), (short)i, (short)j});
            }
        }
    }

    sort(edges.begin(), edges.end());

    vector<int> dp(N + 1, -1);
    dp[0] = 0;
    int ans = 0;

    vector<int> temp(N + 1, -1);
    vector<int> touched;
    touched.reserve(N);

    int i = 0;
    int E = edges.size();
    while (i < E) {
        int j = i;
        int w = edges[i].w;
        while (j < E && edges[j].w == w) ++j;

        for (int k = i; k < j; ++k) {
            int u = edges[k].u;
            int v = edges[k].v;
            if (dp[u] >= 0) {
                int new_val = dp[u] + 1;
                if (new_val > temp[v]) {
                    if (temp[v] == -1) touched.push_back(v);
                    temp[v] = new_val;
                }
            }
        }

        for (int v : touched) {
            if (temp[v] > dp[v]) {
                dp[v] = temp[v];
                if (dp[v] > ans) ans = dp[v];
            }
            temp[v] = -1;
        }
        touched.clear();
        i = j;
    }

    cout << ans << '\n';
    return 0;
}
